const input = $json.body ?? $json;
const expectedStages = ['chat','workflows','code','projects','skills'];
const next = {chat:'workflows',workflows:'code',code:'projects',projects:'skills',skills:'chat'};
const requiredEvidence = new Set(['code:projects','projects:skills','skills:chat']);
const skillRoutes = {chat:['intent-repair-reader','capability-mode-router'],workflows:['lean-build-orchestrator','capability-mode-router'],code:['lean-build-orchestrator','regression-stagnation-guard','capability-mode-router'],projects:['regression-stagnation-guard','truth-research-optimizer'],skills:['truth-research-optimizer','capability-mode-router']};
const fail = (reason) => { throw new Error(reason); };
const text = (value) => typeof value === 'string' ? value.trim() : '';
if (input.contract !== 'founder-control-room/n8n-conveyor@v2') fail('invalid contract');
if (input.event !== 'conveyor.stage.advance') fail('invalid event');
if (!/^fcr-conveyor-v2:[0-9a-f]{64}$/i.test(input.idempotencyKey ?? '')) fail('invalid idempotency key');
if (!text(input.runId)) fail('runId required');
if (!text(input.projectSlug)) fail('projectSlug required');
if (!text(input.goal)) fail('goal required');
if (!/^[0-9a-f]{40}$/i.test(input.expectedHeadSha ?? '')) fail('expectedHeadSha must be exact');
if (!expectedStages.includes(input.fromStage) || !expectedStages.includes(input.toStage)) fail('invalid stage');
if (next[input.fromStage] !== input.toStage) fail('invalid stage transition');
const evidenceUrls = Array.isArray(input.evidenceUrls) ? [...new Set(input.evidenceUrls.map(text).filter(Boolean))].sort() : fail('evidenceUrls must be an array');
for (const value of evidenceUrls) { let url; try { url = new URL(value); } catch { fail('invalid evidence URL'); } if (url.protocol !== 'https:' && !(url.protocol === 'http:' && ['localhost','127.0.0.1'].includes(url.hostname))) fail('invalid evidence URL'); }
if (requiredEvidence.has(`${input.fromStage}:${input.toStage}`) && evidenceUrls.length === 0) fail('evidence required');
const authority = input.authority ?? {};
if (authority.advanceStage !== true || authority.merge !== false || authority.deploy !== false || authority.publish !== false || authority.sendExternal !== false) fail('authority envelope rejected');
const skillIds = skillRoutes[input.toStage];
const receiptSeed = JSON.stringify([text(input.idempotencyKey),text(input.runId),text(input.projectSlug),text(input.goal),text(input.expectedHeadSha).toLowerCase(),input.fromStage,input.toStage,skillIds,evidenceUrls]);
return [{json:{accepted:true,receiptSeed,contract:'founder-control-room/n8n-conveyor@v2',event:'conveyor.stage.accepted',idempotencyKey:text(input.idempotencyKey),runId:text(input.runId),projectSlug:text(input.projectSlug),fromStage:input.fromStage,toStage:input.toStage,expectedHeadSha:text(input.expectedHeadSha).toLowerCase(),evidenceUrls,skillIds}}];

const crypto = require('crypto');
const receiptId = `fcr-conveyor-receipt-v2:${crypto.createHash('sha256').update($json.receiptSeed).digest('hex')}`;
return [{json:{receiptId,status:'accepted',contract:$json.contract,event:$json.event,idempotencyKey:$json.idempotencyKey,runId:$json.runId,projectSlug:$json.projectSlug,fromStage:$json.fromStage,toStage:$json.toStage,expectedHeadSha:$json.expectedHeadSha,skillIds:$json.skillIds,evidenceUrls:$json.evidenceUrls}}];
